import{_ as s,o as e,c as n,a0 as t}from"./chunks/framework.BpJS36ta.js";const h=JSON.parse('{"title":"Class","description":"","frontmatter":{},"headers":[],"relativePath":"syntax/class.md","filePath":"syntax/class.md"}'),i={name:"syntax/class.md"};function o(d,a,r,c,l,p){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="class" tabindex="-1">Class <a class="header-anchor" href="#class" aria-label="Permalink to &quot;Class&quot;">​</a></h1><h2 id="apa-yang-bisa-ditulis" tabindex="-1">Apa yang bisa ditulis? <a class="header-anchor" href="#apa-yang-bisa-ditulis" aria-label="Permalink to &quot;Apa yang bisa ditulis?&quot;">​</a></h2><p>Class dideklarasikan <strong>tanpa keyword</strong> — penandanya <code>: Type</code> yang merujuk struct yang sudah ada:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MonsterType {}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Monster: MonsterType {</span></span>
<span class="line"><span>    construct() {</span></span>
<span class="line"><span>        this.set(null)</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="kapan-digunakan" tabindex="-1">Kapan digunakan? <a class="header-anchor" href="#kapan-digunakan" aria-label="Permalink to &quot;Kapan digunakan?&quot;">​</a></h2><p>Gunakan class ketika struct butuh <strong>perilaku</strong> (method), bukan hanya data. Struct = data, class = presentation di atas struct. Deklarasi <code>main extends Monster {}</code> juga membentuk class — <code>extends</code> otomatis menandai class tanpa perlu anotasi tambahan.</p><h2 id="apa-hasilnya" tabindex="-1">Apa hasilnya? <a class="header-anchor" href="#apa-hasilnya" aria-label="Permalink to &quot;Apa hasilnya?&quot;">​</a></h2><p><code>Name: Type {}</code> menghasilkan deklarasi class: nama class, type yang dirujuk, dan body berisi method. Di AST dikenali sebagai node <code>Class</code> (terpisah dari <code>Struct</code>), dan formatter mempertahankan anotasi <code>: Type</code> saat round-trip (<code>rupa fmt</code>).</p><h3 id="catatan-status" tabindex="-1">Catatan status <a class="header-anchor" href="#catatan-status" aria-label="Permalink to &quot;Catatan status&quot;">​</a></h3><p>Fitur dalam pengembangan. Yang sudah aktif:</p><ul><li>Parsing <code>Name: Type {}</code> → node Class (interpreter + IR).</li><li>Registrasi type + layout field sejajar struct.</li><li>Method di body dikenali sebagai function declaration.</li><li><code>construct()</code> dijalankan otomatis saat deklarasi (sifat sementara untuk debugging, karena <code>rupa go</code> belum aktif).</li></ul><p>Yang belum aktif: <code>this</code>/closure di runtime, <code>super</code> dispatch, <code>@created</code>, <code>@input</code>. Nama constructor ditetapkan <code>construct()</code>.</p><p>Rencana entry point: class <strong>bukan</strong> entry point script mode — nanti <code>rupa &lt;file.rp&gt;</code> menolak auto-run class-main; menjalankannya adalah peran <code>rupa go</code> (design <code>rupa_go.txt</code>: runner class, prioritas target web).</p>`,13)])])}const m=s(i,[["render",o]]);export{h as __pageData,m as default};
